"""Dynamic MCP discovery plus handler-path tool authorization."""

from __future__ import annotations

from collections.abc import Callable, Mapping
from dataclasses import dataclass, replace
from functools import partial
from threading import RLock
from typing import Any, ContextManager

import anyio
from mcp.server.fastmcp import FastMCP
from mcp.server.fastmcp.exceptions import ToolError
from mcp.server.lowlevel import NotificationOptions
from mcp.server.stdio import stdio_server
from mcp.types import Icon, ToolAnnotations

from pyocd_debug_mcp.kernel.operations import (
    BoardBusyError,
    ManagedOperation,
    OperationTimeoutError,
    dispatch,
    operation_manager,
    operation_timeout_seconds,
    wrap_layer2_response,
)


@dataclass(frozen=True, slots=True)
class ToolDefinition:
    """Discovery and authorization metadata for one MCP tool."""

    name: str
    hidden_by_default: bool = False
    locked_by_default: bool = False
    prerequisite: str | None = None


class ToolRegistry:
    """Own tool visibility and per-board physical lock state.

    Discovery is deliberately derived from, but weaker than, authorization. A
    hidden tool is still registered with FastMCP so a stale client can call its
    name and receive the same explicit locked-tool refusal.
    """

    def __init__(self) -> None:
        self._definitions: dict[str, ToolDefinition] = {}
        self._unlocked_boards: dict[str, set[str]] = {}
        self._guard = RLock()
        self._list_revision = 0

    @property
    def list_revision(self) -> int:
        with self._guard:
            return self._list_revision

    def register(
        self,
        name: str,
        *,
        hidden: bool = False,
        locked: bool = False,
        prerequisite: str | None = None,
    ) -> ToolDefinition:
        if not name:
            raise ValueError("tool name must not be empty")
        if locked and not prerequisite:
            prerequisite = f"{name}-plan"

        definition = ToolDefinition(
            name=name,
            hidden_by_default=hidden,
            locked_by_default=locked,
            prerequisite=prerequisite,
        )
        with self._guard:
            existing = self._definitions.get(name)
            if existing is not None:
                if existing != definition:
                    raise ValueError(f"tool '{name}' is already registered with different policy")
                return existing
            self._definitions[name] = definition
            self._unlocked_boards[name] = set()
            if not hidden:
                self._list_revision += 1
        return definition

    def configure(
        self,
        name: str,
        *,
        hidden: bool,
        locked: bool,
        prerequisite: str | None = None,
    ) -> ToolDefinition:
        """Set initial policy for an already registered FastMCP tool."""

        if locked and not prerequisite:
            prerequisite = f"{name}-plan"
        with self._guard:
            current = self._require_definition(name)
            was_advertised = self._is_advertised(current)
            updated = replace(
                current,
                hidden_by_default=hidden,
                locked_by_default=locked,
                prerequisite=prerequisite,
            )
            self._definitions[name] = updated
            if not locked:
                self._unlocked_boards[name].clear()
            is_advertised = self._is_advertised(updated)
            if was_advertised != is_advertised:
                self._list_revision += 1
            return updated

    def unregister(self, name: str) -> None:
        with self._guard:
            definition = self._require_definition(name)
            was_advertised = self._is_advertised(definition)
            del self._definitions[name]
            del self._unlocked_boards[name]
            if was_advertised:
                self._list_revision += 1

    def advertised(self) -> tuple[str, ...]:
        with self._guard:
            return tuple(
                name
                for name, definition in self._definitions.items()
                if self._is_advertised(definition)
            )

    def definition(self, name: str) -> ToolDefinition:
        with self._guard:
            return self._require_definition(name)

    def is_registered(self, name: str) -> bool:
        """Return whether policy metadata exists without raising for an optional alias."""

        with self._guard:
            return name in self._definitions

    def unlock(self, name: str, board_id: str) -> None:
        if not board_id:
            raise ValueError("board_id must not be empty")
        with self._guard:
            definition = self._require_definition(name)
            if not definition.locked_by_default:
                return
            was_advertised = self._is_advertised(definition)
            self._unlocked_boards[name].add(board_id)
            if was_advertised != self._is_advertised(definition):
                self._list_revision += 1

    def relock(self, name: str, board_id: str) -> None:
        with self._guard:
            definition = self._require_definition(name)
            was_advertised = self._is_advertised(definition)
            self._unlocked_boards[name].discard(board_id)
            if was_advertised != self._is_advertised(definition):
                self._list_revision += 1

    def reset(self) -> None:
        """Restore every guarded tool to its default run-start lock state."""

        with self._guard:
            before = self.advertised()
            for boards in self._unlocked_boards.values():
                boards.clear()
            if before != self.advertised():
                self._list_revision += 1

    def is_unlocked(self, name: str, board_id: str | None) -> bool:
        with self._guard:
            definition = self._require_definition(name)
            if not definition.locked_by_default:
                return True
            return board_id is not None and board_id in self._unlocked_boards[name]

    def require_unlocked(self, name: str, board_id: str | None) -> None:
        if self.is_unlocked(name, board_id):
            return
        definition = self.definition(name)
        prerequisite = definition.prerequisite or f"{name}-plan"
        board_text = f" for board '{board_id}'" if board_id else ""
        raise ToolError(
            f"Tool '{name}' is locked{board_text}. Call '{prerequisite}' first."
        )

    def _require_definition(self, name: str) -> ToolDefinition:
        try:
            return self._definitions[name]
        except KeyError as exc:
            raise ToolError(f"Unknown tool: {name}") from exc

    def _is_advertised(self, definition: ToolDefinition) -> bool:
        return not definition.hidden_by_default or bool(self._unlocked_boards[definition.name])


TimeoutResolver = Callable[[str, Mapping[str, object] | None], float]
InvocationGuard = Callable[[str, str, Mapping[str, object]], None]
ExecutionLockResolver = Callable[[str], ContextManager[object]]
OperationResourceBinder = Callable[[ManagedOperation], None]
OperationFinalizerResolver = Callable[[str, str, Mapping[str, object]], Callable[[], None] | None]


@dataclass(frozen=True, slots=True)
class GuardedDispatchPolicy:
    guard: InvocationGuard
    lock_for_board: ExecutionLockResolver


class RegistryFastMCP(FastMCP):
    """FastMCP adapter with dynamic discovery, locks, and bounded dispatch."""

    def __init__(
        self,
        name: str | None = None,
        *,
        registry: ToolRegistry | None = None,
        timeout_resolver: TimeoutResolver = operation_timeout_seconds,
        **settings: Any,
    ) -> None:
        self.registry = registry or ToolRegistry()
        self._timeout_resolver = timeout_resolver
        self._guarded_dispatch: dict[str, GuardedDispatchPolicy] = {}
        self._layer2_tools: set[str] = set()
        self._operation_resource_binder: OperationResourceBinder | None = None
        self._finalizer_resolver: OperationFinalizerResolver | None = None
        super().__init__(name=name, **settings)

    def configure_operation_resources(self, binder: OperationResourceBinder) -> None:
        """Bind persistent board resources into each managed hardware invocation."""

        self._operation_resource_binder = binder

    def configure_finalizers(self, resolver: OperationFinalizerResolver) -> None:
        """Configure strict resolution of structured on-exit actions."""

        self._finalizer_resolver = resolver

    def configure_layer2(self, name: str) -> None:
        """Mark a registered hardware action for common failure wrapping."""

        self.registry.definition(name)
        self._layer2_tools.add(name)

    def configure_guarded_dispatch(
        self,
        name: str,
        *,
        guard: InvocationGuard,
        lock_for_board: ExecutionLockResolver,
    ) -> None:
        """Bind one registered synchronous tool to plan enforcement and its board lock."""

        self.registry.definition(name)
        self._guarded_dispatch[name] = GuardedDispatchPolicy(guard, lock_for_board)

    def add_tool(
        self,
        fn: Callable[..., Any],
        name: str | None = None,
        title: str | None = None,
        description: str | None = None,
        annotations: ToolAnnotations | None = None,
        icons: list[Icon] | None = None,
        meta: dict[str, Any] | None = None,
        structured_output: bool | None = None,
    ) -> None:
        super().add_tool(
            fn,
            name=name,
            title=title,
            description=description,
            annotations=annotations,
            icons=icons,
            meta=meta,
            structured_output=structured_output,
        )
        self.registry.register(name or fn.__name__)

    def remove_tool(self, name: str) -> None:
        super().remove_tool(name)
        self.registry.unregister(name)

    async def list_tools(self):  # type: ignore[no-untyped-def]
        tools = await super().list_tools()
        advertised = frozenset(self.registry.advertised())
        return [tool for tool in tools if tool.name in advertised]

    async def call_tool(self, name: str, arguments: dict[str, Any]):  # type: ignore[no-untyped-def]
        board_value = arguments.get("board_id")
        board_id = board_value if isinstance(board_value, str) and board_value else None
        try:
            self.registry.require_unlocked(name, board_id)
        except ToolError as exc:
            if name in self._layer2_tools:
                raise ToolError(wrap_layer2_response(str(exc))) from exc
            raise
        revision_before = self.registry.list_revision
        dispatch_policy = self._guarded_dispatch.get(name)
        before_execution = None
        execution_lock = None
        if dispatch_policy is not None:
            if board_id is None:
                raise ToolError(f"Guarded tool '{name}' requires a non-empty board_id.")
            before_execution = partial(
                dispatch_policy.guard,
                name,
                board_id,
                dict(arguments),
            )
            execution_lock = dispatch_policy.lock_for_board(board_id)
        tool = self._tool_manager.get_tool(name)
        if tool is None:
            raise ToolError(f"Unknown tool: {name}")
        context = self.get_context()
        timeout = self._timeout_resolver(name, arguments)
        finalizer = None
        if arguments.get("on_exit") is not None:
            if board_id is None or self._finalizer_resolver is None:
                raise ToolError(f"Tool '{name}' cannot accept an on_exit finalizer.")
            try:
                finalizer = self._finalizer_resolver(name, board_id, arguments)
            except ValueError as exc:
                raise ToolError(str(exc)) from exc
        try:
            request_id = context.request_id
        except ValueError:
            request_id = None

        try:
            if tool.is_async:

                async def invoke_async():  # type: ignore[no-untyped-def]
                    return await tool.run(arguments, context=context, convert_result=True)

                return await dispatch(
                    name,
                    board_id,
                    invoke_async,
                    timeout,
                    before_execution=before_execution,
                    execution_lock=execution_lock,
                    request_id=request_id,
                    serialize_board=name != "action_batch",
                    resource_binder=self._operation_resource_binder
                    if name in self._layer2_tools
                    else None,
                    finalizer=finalizer,
                )

            def invoke_sync():  # type: ignore[no-untyped-def]
                return anyio.run(
                    partial(tool.run, arguments, context=context, convert_result=True)
                )

            return await dispatch(
                name,
                board_id,
                invoke_sync,
                timeout,
                before_execution=before_execution,
                execution_lock=execution_lock,
                request_id=request_id,
                resource_binder=self._operation_resource_binder
                if name in self._layer2_tools
                else None,
                finalizer=finalizer,
            )
        except (OperationTimeoutError, BoardBusyError) as exc:
            message = str(exc)
            if name in self._layer2_tools:
                message = wrap_layer2_response(message)
            raise ToolError(message) from exc
        except ToolError as exc:
            if name in self._layer2_tools:
                raise ToolError(wrap_layer2_response(str(exc))) from exc
            raise
        except Exception as exc:
            if name in self._layer2_tools:
                raise ToolError(wrap_layer2_response(str(exc))) from exc
            raise
        finally:
            if self.registry.list_revision != revision_before:
                await self._send_tool_list_changed()

    def create_initialization_options(self):  # type: ignore[no-untyped-def]
        """Advertise the tool-list notification capability to MCP clients."""

        return self._mcp_server.create_initialization_options(
            NotificationOptions(tools_changed=True)
        )

    async def _send_tool_list_changed(self) -> None:
        context = self.get_context()
        try:
            session = context.session
        except ValueError:
            return
        await session.send_tool_list_changed()

    async def run_stdio_async(self) -> None:
        """Run stdio while advertising dynamic tool-list notifications."""

        try:
            async with stdio_server() as (read_stream, write_stream):
                await self._mcp_server.run(
                    read_stream,
                    write_stream,
                    self.create_initialization_options(),
                )
        finally:
            operation_manager.cancel_all("stdio client EOF or server shutdown")

"""Sequential same-board batches that reuse the standard MCP dispatch path."""

from __future__ import annotations

import json
from collections.abc import Awaitable, Callable
from typing import Any

from pydantic import BaseModel, ConfigDict, Field, JsonValue

from pyocd_debug_mcp.kernel.operations import SAFE_EXIT_REMINDER

class BatchChild(BaseModel):
    """One JSON-only MCP child call with no extra or authority-bearing fields."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    tool_name: str = Field(min_length=1)
    arguments: dict[str, JsonValue]


ChildDispatcher = Callable[[str, dict[str, Any]], Awaitable[Any]]
ToolLookup = Callable[[str], bool]


class BatchValidationError(ValueError):
    """The complete child list failed structural validation before execution."""


def _validate_children(
    board_id: str,
    children: list[BatchChild],
    *,
    tool_exists: ToolLookup,
) -> tuple[BatchChild, ...]:
    board = board_id.strip()
    if not board:
        raise BatchValidationError("board_id must be non-empty")
    if board != board_id:
        raise BatchValidationError("board_id must not contain surrounding whitespace")
    if not children:
        raise BatchValidationError("actions must contain at least one child call")
    validated: list[BatchChild] = []
    for index, child in enumerate(children):
        name = child.tool_name.strip()
        if name.casefold() == "action_batch":
            raise BatchValidationError(
                f"actions[{index}] is a nested action_batch; nested batches are forbidden"
            )
        if name != child.tool_name:
            raise BatchValidationError(
                f"actions[{index}].tool_name must not contain surrounding whitespace"
            )
        if not tool_exists(name):
            raise BatchValidationError(
                f"actions[{index}] names unknown tool '{name}'"
            )
        child_board = child.arguments.get("board_id")
        if not isinstance(child_board, str) or not child_board:
            raise BatchValidationError(
                f"actions[{index}] must contain a non-empty string board_id"
            )
        if child_board != board:
            raise BatchValidationError(
                f"actions[{index}] targets board '{child_board}', not shared board '{board}'"
            )
        validated.append(child)
    return tuple(validated)


def _json_result(value: Any) -> JsonValue:
    if isinstance(value, list):
        return [
            item.model_dump(mode="json") if isinstance(item, BaseModel) else item
            for item in value
        ]
    if isinstance(value, BaseModel):
        return value.model_dump(mode="json")
    if value is None or isinstance(value, (str, int, float, bool, dict)):
        return value
    return str(value)


def build_batch_handlers(
    dispatch_child: ChildDispatcher,
    *,
    tool_exists: ToolLookup,
) -> dict[str, Callable[..., Awaitable[str]]]:
    """Build the batch tool without introducing a second authorization path."""

    async def action_batch(board_id: str, actions: list[BatchChild]) -> str:
        """Execute bounded same-board child calls through their normal dispatch path.

        Use an accepted *-plan's server-generated one-child fallback unchanged when a client's
        callable bindings remain static. Never invent hidden children or use a batch to bypass
        plans, permission, validation, gates, freshness, timeouts, budgets, locks, or cleanup;
        every child independently traverses those normal checks.
        """

        validated = _validate_children(board_id, actions, tool_exists=tool_exists)
        completed: list[dict[str, JsonValue]] = []
        failure: dict[str, JsonValue] | None = None

        for index, child in enumerate(validated):
            arguments = dict(child.arguments)
            try:
                result = await dispatch_child(child.tool_name, arguments)
            except Exception as exc:  # child dispatch owns the typed authorization failure
                failure = {
                    "index": index,
                    "tool_name": child.tool_name,
                    "error_type": type(exc).__name__,
                    "message": str(exc),
                }
                break
            completed.append(
                {
                    "index": index,
                    "tool_name": child.tool_name,
                    "result": _json_result(result),
                }
            )

        payload: dict[str, JsonValue] = {
            "status": "batch_completed" if failure is None else "batch_failed",
            "board_id": board_id,
            "completed": list(completed),
            "failure": dict(failure) if failure is not None else None,
        }
        body = json.dumps(
            payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")
        )
        return f"{body}\n{SAFE_EXIT_REMINDER}"

    return {"action_batch": action_batch}


__all__ = [
    "BatchChild",
    "BatchValidationError",
    "build_batch_handlers",
]

"""Adversarial registered-boundary tests for H01 CL-001."""

from __future__ import annotations

import unittest
from types import SimpleNamespace
from typing import Mapping

from mcp.server.fastmcp import FastMCP
from mcp.server.fastmcp.exceptions import ToolError

from pyocd_debug_mcp.guardrails.plan_defs import PLAN_TOOL_DEFINITIONS, PlanDefinition
from pyocd_debug_mcp.guardrails.plan_engine import PlanEngine
from pyocd_debug_mcp.kernel.run_state import ServerRun
from pyocd_debug_mcp.tools.plans import register_plan_tools


class _Registry:
    def is_registered(self, name: str) -> bool:
        del name
        return True

    def unlock(self, name: str, board_id: str) -> None:
        del name, board_id

    def relock(self, name: str, board_id: str) -> None:
        del name, board_id

    def is_unlocked(self, name: str, board_id: str | None) -> bool:
        del name, board_id
        return True


class _CapturingEngine:
    def __init__(self) -> None:
        self.calls: list[dict[str, object]] = []

    def submit(
        self,
        tool_name: str,
        fields: Mapping[str, object],
        *,
        session_id: str | None = None,
    ) -> SimpleNamespace:
        del tool_name, session_id
        self.calls.append(dict(fields))
        return SimpleNamespace(message="captured")


class H01PlanTextPreservationTests(unittest.IsolatedAsyncioTestCase):
    """Exercise FastMCP's real invocation path, never a direct handler/model surrogate."""

    def _registered_tool(
        self,
        definition: PlanDefinition,
        engine: object,
    ) -> object:
        mcp = FastMCP("h01-plan-text-preservation")
        register_plan_tools(mcp, engine, (definition,), lambda board_id: f"session:{board_id}")
        tool = mcp._tool_manager.get_tool(definition.plan_tool_name)  # type: ignore[reportPrivateUsage]
        self.assertIsNotNone(tool)
        return tool

    @staticmethod
    def _all_null(definition: PlanDefinition) -> dict[str, object]:
        return {field.name: None for field in definition.null_fields}

    @staticmethod
    def _populated_envelope() -> dict[str, object]:
        return {
            "board_id": "board_1",
            "hypothesis": "the observed state has one concrete cause",
            "strategy": "compare the next observation with the predicted result",
            "hypothesis_made": True,
            "strategy_evaluated": True,
            "expected_fail_return": "the observation contradicts the stated cause",
            "expected_success_return": "the observation matches the stated cause",
            "max_calls": 1,
            "max_calls_buffer": 0,
            "action_parameters": {},
        }

    async def test_cl001_json_looking_text_reaches_a_generated_plan_handler_verbatim(self) -> None:
        """No JSON-looking text spelling may be converted before the generated handler."""
        definition = PLAN_TOOL_DEFINITIONS["board_setup-plan"]
        engine = _CapturingEngine()
        tool = self._registered_tool(definition, engine)

        await tool.run(self._all_null(definition), convert_result=True)  # type: ignore[union-attr]
        self.assertEqual(engine.calls[-1], self._all_null(definition))

        for value in ("null", "true", "[]", "{}"):
            with self.subTest(value=value):
                fields = self._populated_envelope()
                fields["hypothesis"] = value
                fields["user_permission"] = value
                await tool.run(fields, convert_result=True)  # type: ignore[union-attr]
                captured = engine.calls[-1]
                self.assertIsInstance(captured["hypothesis"], str)
                self.assertEqual(captured["hypothesis"], value)
                self.assertIsInstance(captured["user_permission"], str)
                self.assertEqual(captured["user_permission"], value)

    async def test_cl001_null_text_reaches_reasoning_validation_as_a_placeholder(self) -> None:
        """Every signed placeholder must reach reasoning validation as literal text."""
        definition = PLAN_TOOL_DEFINITIONS["connect_override-plan"]
        placeholders = ("n/a", "na", "none", "null", "placeholder", "tbd", "todo", "unknown")
        for field_name in ("hypothesis", "strategy", "expected_fail_return", "expected_success_return"):
            for placeholder in placeholders:
                with self.subTest(field=field_name, placeholder=placeholder):
                    engine = PlanEngine(ServerRun(), _Registry())
                    tool = self._registered_tool(definition, engine)
                    await tool.run(self._all_null(definition), convert_result=True)  # type: ignore[union-attr]
                    fields = self._populated_envelope()
                    fields[field_name] = placeholder
                    fields["action_parameters"] = {
                        "probe_uid": None,
                        "target_override": None,
                        "external_board_config": None,
                    }
                    with self.assertRaisesRegex(
                        ToolError,
                        rf"{field_name} must be concrete, not placeholder text",
                    ) as raised:
                        await tool.run(fields, convert_result=True)  # type: ignore[union-attr]
                    self.assertNotIn("must not be NULL", str(raised.exception))

    async def test_cl001_actual_null_keeps_the_existing_initialization_and_field_error_contract(self) -> None:
        definition = PLAN_TOOL_DEFINITIONS["connect_override-plan"]
        engine = PlanEngine(ServerRun(), _Registry())
        tool = self._registered_tool(definition, engine)

        initialized = await tool.run(self._all_null(definition), convert_result=True)  # type: ignore[union-attr]
        self.assertIn("Plan initialization for connect_override-plan.", initialized[0].text)

        fields = self._populated_envelope()
        fields["hypothesis"] = None
        fields["action_parameters"] = {
            "probe_uid": None,
            "target_override": None,
            "external_board_config": None,
        }
        with self.assertRaisesRegex(ToolError, "hypothesis.*must not be NULL"):
            await tool.run(fields, convert_result=True)  # type: ignore[union-attr]


